let raw = $json.text || $json.output || '';

// Si vino como objeto ya parseado, lo usamos directo
if (typeof raw === 'object') {
  return { json: { output: raw } };
}

// Si vino como texto, le sacamos los ```json y ``` de los costados
let clean = raw.replace(/```json/g, '').replace(/```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = { es_comprobante: false, motivo: 'No se pudo interpretar la respuesta de la IA', monto: null, fecha: null, metodo: 'No identificado' };
}

return { json: { output: parsed } };
